//! 🧪️ Supplied native bytes return without copy and close only through their still-live original supplier.
use semio_framework_job::*;
use semio_framework_value_testing_allocator as _;
#[cfg(test)] use semio_framework_job_payload::payload_pages_and_ledger::JobPayloadStream;
#[path="../../../🧪️testing/📬️payload/🦀️.rs"]
mod original_payload;
static RETURNS:OriginalJobPageReturnRegistry<1>=OriginalJobPageReturnRegistry::new();
static CONTIGUOUS_RETURNS:OriginalJobBytesReturnRegistry<1>=OriginalJobBytesReturnRegistry::with_return_wake(original_contiguous_notice);
fn original_contiguous_notice(){}

/// 🎫️ The fuel one staged reservation turn is quoted: the Source loan it admits plus its registry control.
fn reservation_work(cx:&StepContext<'_>)->u64{cx.original_source_parent().and_then(|parent|parent.loan_admission_work_demand()).expect("original Source loan work quote")+1}
/// 🎫️ The fuel the contiguous backing's settled construction is quoted.
fn construction_work(length:usize)->u64{original_construction_settled_quote::<Vec<u8>>(OriginalConstructionDemand{items:1,copy_bytes:0,capacity_bytes:length,release_bytes:0,depth:1},1).expect("original contiguous construction quote").1}
fn page_reservation<const N:usize>(registry:&'static OriginalJobPageReturnRegistry<N>,original:&mut original_payload::OriginalTestPayload)->OriginalJobPageReservation<N>{
 let mut output=None;for _ in 0..64{if original.caller.turn(original_payload::BIRTH,|cx|cx.with_original_work_loan(reservation_work(cx),cx.original_absolute_deadline_us(),|cx|registry.reserve(&mut output,cx))).unwrap(){return output.take().unwrap()}}panic!("original page reservation did not finish within its staged admission bound")
}
fn bytes_reservation<const N:usize>(registry:&'static OriginalJobBytesReturnRegistry<N>,original:&mut original_payload::OriginalTestPayload)->OriginalJobBytesReservation<N>{
 let mut output=None;for _ in 0..64{if original.caller.turn(original_payload::BIRTH,|cx|cx.with_original_work_loan(reservation_work(cx),cx.original_absolute_deadline_us(),|cx|registry.reserve(&mut output,cx))).unwrap(){return output.take().unwrap()}}panic!("original bytes reservation did not finish within its staged admission bound")
}

fn supply_page<const N:usize>(original:&mut original_payload::OriginalTestPayload,reservation:&mut OriginalJobPageReservation<N>,grant:RetainedCloneGrant)->OriginalSuppliedJobPage{
 let mut output=None;let grant=RetainedCloneGrant{maximum_copy_bytes:original.builder.published().unwrap().original_page_transfer_demand(&None).expect("original page transfer quote").copy_bytes,..grant};for _ in 0..2{if original.original_turn(grant,|builder,cx|builder.supply_last_page(reservation,&mut output,cx)).unwrap(){return output.take().unwrap()}}panic!("original page transfer did not settle its real alias and move turns")
}

#[test]
fn original_contiguous_bytes_keep_exact_birth_fill_and_return_on_the_same_source(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../📦️bytes/🔣️.json")).unwrap();let length=law["capacityBytes"].as_u64().unwrap()as usize;
 let mut original=original_payload::OriginalTestPayload::admit_single_page(OperationId(96004),Generation(10),JobPayloadStream::CommitOutput,b"original contiguous",JOB_PAYLOAD_PAGE_BYTES);original.birth_returns();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:32768,maximum_release_bytes:1048576,maximum_depth:64};let mut bytes=None;
 for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:16384,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(answer,heap)=original_payload::observe(||original.original_turn(denied,|_,cx|OriginalContiguousJobBytes::admit(length,&mut bytes,cx)));assert!(!answer.unwrap());assert!(bytes.is_none());assert_eq!(heap,(0,0));}
 for turn in 0..64{let(answer,heap)=original_payload::observe(||original.original_turn(original_payload::BIRTH,|_,cx|cx.with_original_work_loan(reservation_work(cx).max(construction_work(length)),cx.original_absolute_deadline_us(),|cx|OriginalContiguousJobBytes::admit(length,&mut bytes,cx))));if answer.unwrap(){assert_eq!(heap,(length,0));break}assert!(turn<63);}assert!(bytes.as_ref().unwrap().ready());let source=original.caller.turn(grant,|cx|Ok(cx.original_source_parent()?.source_identity()?)).unwrap();
 let data:Vec<u8>=(0..length).map(|index|(index%251)as u8).collect();for part in data.chunks(4096){let(answer,heap)=original_payload::observe(||original.original_turn(grant,|_,cx|bytes.as_mut().unwrap().append(part,cx)));assert!(answer.unwrap());assert_eq!(heap,(0,0));}let pointer=bytes.as_ref().unwrap().borrowed_bytes().unwrap().as_ptr();
 let mut foreign=original_payload::OriginalTestPayload::admit_single_page(OperationId(96004),Generation(10),JobPayloadStream::CommitOutput,b"foreign",JOB_PAYLOAD_PAGE_BYTES);let(answer,heap)=original_payload::observe(||foreign.original_turn(grant,|_,cx|bytes.as_mut().unwrap().append(&[],cx)));assert!(answer.is_err());assert_eq!(heap,(0,0));foreign.close();
 let mut reservation=bytes_reservation(&CONTIGUOUS_RETURNS,&mut original);let mut supplied=None;let(answer,heap)=original_payload::observe(||original.original_turn(grant,|_,cx|reservation.publish(&mut bytes,&mut supplied,cx)));assert!(answer.unwrap());assert_eq!(heap,(0,0));assert!(bytes.is_none());let supplied=supplied.unwrap();assert_eq!(supplied.bytes(),data.as_slice());assert_eq!(supplied.bytes().as_ptr(),pointer);assert_eq!(supplied.source_identity(),source);assert_eq!(original_payload::observe(||drop(supplied)).1,(0,0));assert!(CONTIGUOUS_RETURNS.has_returned_source(source));
 for capture in[true,false]{original.original_turn(grant,|_,cx|cx.with_original_work_loan(0,cx.original_absolute_deadline_us(),|cx|{let work=cx.original_work_units_spent();let step=CONTIGUOUS_RETURNS.close_returned_step(cx)?;assert_eq!(step.progress(),RetainedCloneProgress{copied_items:1,copied_bytes:semio_framework_job_payload::OriginalReturnEscrowAccounting::witness_copy(capture,!capture,0).unwrap(),..Default::default()});assert_eq!(cx.original_work_units_spent()-work,1);Ok(())})).unwrap();}
 for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_release_bytes:16384,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(answer,heap)=original_payload::observe(||original.original_turn(denied,|_,cx|CONTIGUOUS_RETURNS.close_returned_step(cx)));assert_eq!(answer.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert!(CONTIGUOUS_RETURNS.retains_source(source));}
 let mut released=0;for turn in 0..24{if !CONTIGUOUS_RETURNS.retains_source(source){break}let(answer,heap)=original_payload::observe(||original.original_turn(grant,|_,cx|CONTIGUOUS_RETURNS.close_returned_step(cx)));let step=answer.unwrap();assert!(!matches!(step,InteractiveJobCloseStep::Complete{..}));let progress=step.progress();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));released+=heap.1;assert!(turn<23)}assert_eq!(released,law["supplierReleaseBytes"].as_u64().unwrap()as usize);drop(reservation);original.close();assert_eq!(original_payload::observe(||drop(original)).1,(0,0));
}
static ORDERED_RETURNS:OriginalJobPageReturnRegistry<3>=OriginalJobPageReturnRegistry::new();
static WAKE_SOURCE:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
static WAKE_COUNT:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
static NOTIFIED_RETURNS:OriginalJobPageReturnRegistry<1>=OriginalJobPageReturnRegistry::with_return_wake(original_return_notice);
fn original_return_notice(){let source=WAKE_SOURCE.load(std::sync::atomic::Ordering::Acquire);assert!(NOTIFIED_RETURNS.has_returned_source(source));WAKE_COUNT.fetch_add(1,std::sync::atomic::Ordering::AcqRel);}

#[test]
fn original_supplied_page_notification_observes_published_return_without_owner_or_closure_birth(){
 let mut original=original_payload::OriginalTestPayload::admit_single_page(OperationId(96003),Generation(9),JobPayloadStream::CommitOutput,b"return wake",JOB_PAYLOAD_PAGE_BYTES);original.birth_returns();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:JOB_PAYLOAD_PAGE_BYTES,maximum_release_bytes:1048576,maximum_depth:64};
 let source=original.caller.turn(grant,|cx|Ok(cx.original_source_parent()?.source_identity()?)).unwrap();WAKE_SOURCE.store(source,std::sync::atomic::Ordering::Release);WAKE_COUNT.store(0,std::sync::atomic::Ordering::Release);
 let mut reservation=page_reservation(&NOTIFIED_RETURNS,&mut original);let page=supply_page(&mut original,&mut reservation,grant);assert_eq!(WAKE_COUNT.load(std::sync::atomic::Ordering::Acquire),0);assert!(!NOTIFIED_RETURNS.has_returned_source(source));
 assert_eq!(original_payload::observe(||drop(page)).1,(0,0));assert_eq!(WAKE_COUNT.load(std::sync::atomic::Ordering::Acquire),1);assert!(NOTIFIED_RETURNS.has_returned_source(source));
 for turn in 0..32{if !NOTIFIED_RETURNS.retains_source(source){break}original.original_turn(grant,|_,cx|NOTIFIED_RETURNS.close_returned_step(cx)).unwrap();assert!(turn<31)}
 let reservation=page_reservation(&NOTIFIED_RETURNS,&mut original);assert_eq!(original_payload::observe(||drop(reservation)).1,(0,0));assert_eq!(WAKE_COUNT.load(std::sync::atomic::Ordering::Acquire),2);
 for turn in 0..16{if !NOTIFIED_RETURNS.retains_source(source){break}original.original_turn(grant,|_,cx|NOTIFIED_RETURNS.close_returned_step(cx)).unwrap();assert!(turn<15)}original.close();
}
#[test]
fn original_supplied_page_returns_same_backing_before_original_source_close(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();assert_eq!(corpus["pageBytes"],JOB_PAYLOAD_PAGE_BYTES);assert_eq!(corpus["operationPages"],JOB_PAYLOAD_OPERATION_PAGES);
 let mut original=original_payload::OriginalTestPayload::admit_single_page(OperationId(96001),Generation(7),JobPayloadStream::CommitOutput,b"original supplier",JOB_PAYLOAD_PAGE_BYTES);original.birth_returns();let pointer=original.builder.published().unwrap().single_page().unwrap().as_ptr();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:JOB_PAYLOAD_PAGE_BYTES,maximum_release_bytes:1048576,maximum_depth:64};
 let source=original.caller.turn(grant,|cx|Ok(cx.original_source_parent()?.source_identity()?)).unwrap();let mut reservation=page_reservation(&RETURNS,&mut original);assert!(RETURNS.retains_source(source));let mut foreign=original_payload::OriginalTestPayload::admit_single_page(OperationId(96001),Generation(7),JobPayloadStream::CommitOutput,b"foreign supplier",JOB_PAYLOAD_PAGE_BYTES);let mut supplied=None;let(answer,heap)=original_payload::observe(||foreign.original_turn(grant,|_,cx|original.builder.supply_last_page(&mut reservation,&mut supplied,cx)));assert!(answer.is_err());assert_eq!(heap,(0,0));assert_eq!(original.builder.published().unwrap().single_page().unwrap().as_ptr(),pointer);
 let mut blocked=None;let(answer,heap)=original_payload::observe(||original.caller.turn(grant,|cx|RETURNS.reserve(&mut blocked,cx)));assert!(!answer.unwrap());assert!(blocked.is_none());assert_eq!(heap,(0,0));assert_eq!(original.caller.receipt(),Default::default());
 for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(answer,heap)=original_payload::observe(||original.original_turn(denied,|builder,cx|builder.supply_last_page(&mut reservation,&mut supplied,cx)));assert!(!answer.unwrap());assert!(supplied.is_none());assert_eq!(heap,(0,0));assert_eq!(original.builder.published().unwrap().single_page().unwrap().as_ptr(),pointer);}
 let(page,heap)=original_payload::observe(||supply_page(&mut original,&mut reservation,RetainedCloneGrant{maximum_copy_bytes:0,..grant}));assert_eq!(heap,(0,0));assert_eq!(page.bytes().as_ptr(),pointer);assert_eq!(page.bytes(),b"original supplier");assert_eq!(page.source_identity(),source);assert!(original.builder.published().unwrap().terminal_is_empty());assert_eq!(original_payload::observe(||drop(reservation)).1,(0,0));
 let(answer,heap)=original_payload::observe(||original.caller.retire_step(grant));assert_eq!(answer.unwrap().progress(),Default::default());assert!(!original.caller.terminal_is_empty());assert_eq!(heap,(0,0));original.caller.cancel().cancel_now();assert_eq!(original_payload::observe(||drop(page)).1,(0,0));assert!(RETURNS.retains_source(source));let(answer,heap)=original_payload::observe(||foreign.original_turn(grant,|_,cx|RETURNS.close_returned_step(cx)));assert_eq!(answer.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert!(RETURNS.retains_source(source));foreign.close();assert_eq!(original_payload::observe(||drop(foreign)).1,(0,0));
 for capture in[true,false]{original.original_turn(grant,|_,cx|cx.with_original_work_loan(0,cx.original_absolute_deadline_us(),|cx|{let work=cx.original_work_units_spent();let step=RETURNS.close_returned_step(cx)?;assert_eq!(step.progress(),RetainedCloneProgress{copied_items:1,copied_bytes:semio_framework_job_payload::OriginalReturnEscrowAccounting::witness_copy(capture,!capture,0).unwrap(),..Default::default()});assert_eq!(cx.original_work_units_spent()-work,1);Ok(())})).unwrap();}
 for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_release_bytes:JOB_PAYLOAD_PAGE_BYTES-1,..grant},RetainedCloneGrant{maximum_depth:1,..grant}]{let(answer,heap)=original_payload::observe(||original.original_turn(denied,|_,cx|RETURNS.close_returned_step(cx)));assert_eq!(answer.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert!(RETURNS.retains_source(source));}
 let mut released=0;for turn in 0..16{if !RETURNS.retains_source(source){break}let(answer,heap)=original_payload::observe(||original.original_turn(grant,|_,cx|RETURNS.close_returned_step(cx)));let progress=answer.unwrap().progress();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));released+=heap.1;assert!(turn<15);}assert_eq!(released,JOB_PAYLOAD_PAGE_BYTES);assert!(!RETURNS.retains_source(source));original.close();assert_eq!(original_payload::observe(||drop(original)).1,(0,0));
}

#[test]
fn original_supplied_pages_preserve_ordinals_and_sealed_prefix_during_partial_transfer(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();let mut bytes=vec![0u8;2*JOB_PAYLOAD_PAGE_BYTES+7];for(index,byte)in bytes.iter_mut().enumerate(){*byte=(index/JOB_PAYLOAD_PAGE_BYTES)as u8;}
 let mut original=original_payload::OriginalTestPayload::admit(OperationId(96002),Generation(8),JobPayloadStream::CommitOutput,&bytes,JOB_PAYLOAD_PAGE_BYTES);original.birth_returns();let pointers=std::array::from_fn::<_,3,_>(|index|original.builder.published().unwrap().page(index).unwrap().as_ptr());let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:JOB_PAYLOAD_PAGE_BYTES,maximum_release_bytes:1048576,maximum_depth:64};let source=original.caller.turn(grant,|cx|Ok(cx.original_source_parent()?.source_identity()?)).unwrap();let mut pages:[Option<OriginalSuppliedJobPage>;3]=std::array::from_fn(|_|None);
 for row in corpus["pageOrder"].as_array().unwrap(){let index=row.as_u64().unwrap()as usize;let mut reservation=page_reservation(&ORDERED_RETURNS,&mut original);let(page,heap)=original_payload::observe(||supply_page(&mut original,&mut reservation,RetainedCloneGrant{maximum_copy_bytes:0,..grant}));assert_eq!(heap,(0,0));assert_eq!(page.original_page_index(),index);assert_eq!(page.bytes().as_ptr(),pointers[index]);assert!(page.bytes().iter().all(|byte|*byte==index as u8));assert_eq!(original.builder.published().unwrap().page_count(),index);pages[index]=Some(page);}
 assert!(original.builder.published().unwrap().terminal_is_empty());for(index,page)in pages.iter().enumerate(){assert_eq!(page.as_ref().unwrap().original_page_index(),index);assert_eq!(page.as_ref().unwrap().bytes().as_ptr(),pointers[index]);}assert_eq!(original_payload::observe(||drop(pages)).1,(0,0));let mut released=0;
 for turn in 0..32{if !ORDERED_RETURNS.retains_source(source){break}let(answer,heap)=original_payload::observe(||original.original_turn(grant,|_,cx|ORDERED_RETURNS.close_returned_step(cx)));let progress=answer.unwrap().progress();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));released+=heap.1;assert!(turn<31);}assert_eq!(released,3*JOB_PAYLOAD_PAGE_BYTES);assert!(!ORDERED_RETURNS.retains_source(source));original.close();assert_eq!(original_payload::observe(||drop(original)).1,(0,0));
}

static PREPAID_PAGES:OriginalJobPageReturnRegistry<1>=OriginalJobPageReturnRegistry::new();
static PREPAID_BYTES:OriginalJobBytesReturnRegistry<1>=OriginalJobBytesReturnRegistry::with_return_wake(original_contiguous_notice);
#[test]
fn page_and_bytes_registry_returns_settle_prepaid_witnesses_at_zero_current_cpu(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🎟️held-return/case.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("../🎟️held-return/case.schema.json")).unwrap();for(k,v)in law.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v);}let s=&law["source"];
 let bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let q=RetainedCloneGrant{maximum_items:1,..bank};
 for(index,case)in law["cases"].as_array().unwrap().iter().enumerate(){
  let bytes=case=="bytesReservation";let mut caller=OriginalJobFixtureCaller::admit(OperationId(9630+index as u64),Generation(1),bank,||Some(0),s["deadlineUs"].as_u64().unwrap(),s["fuel"].as_u64().unwrap());caller.birth_returns(bank);let mut page=None;let mut contiguous=None;let mut ready=false;
  for _ in 0..law["maximumAdmissionTurns"].as_u64().unwrap(){ready=caller.refreshed_turn(q,|cx|cx.with_original_work_loan(reservation_work(cx),cx.original_absolute_deadline_us(),|cx|if bytes{PREPAID_BYTES.reserve(&mut contiguous,cx)}else{PREPAID_PAGES.reserve(&mut page,cx)})).unwrap();if ready{break}}assert!(ready);
  let source=caller.refreshed_turn(q,|cx|Ok(cx.original_source_parent()?.source_identity()?)).unwrap();let(_,heap)=original_payload::observe(||{drop(page.take());drop(contiguous.take());});assert_eq!(heap,(0,0));
  for capture in[true,false]{assert_eq!(law["heldWitnesses"].as_u64().unwrap(),2);
   caller.refreshed_turn(q,|cx|cx.with_original_work_loan(law["currentWork"].as_u64().unwrap(),cx.original_absolute_deadline_us(),|cx|{
    let before=cx.retained_progress();let work=cx.original_work_units_spent();let(answer,heap)=original_payload::observe(||if bytes{PREPAID_BYTES.close_returned_step(cx)}else{PREPAID_PAGES.close_returned_step(cx)});answer?;let after=cx.retained_progress();assert_eq!(heap,(0,0));
    assert_eq!(cx.original_work_units_spent()-work,law["witnessWork"].as_u64().unwrap()as u128);assert_eq!(after.copied_items-before.copied_items,law["witnessItems"].as_u64().unwrap()as usize);assert_eq!(after.copied_bytes-before.copied_bytes,semio_framework_job_payload::OriginalReturnEscrowAccounting::witness_copy(capture,!capture,0).unwrap());assert_eq!(after.retained_capacity_bytes-before.retained_capacity_bytes,0);assert_eq!(after.released_bytes-before.released_bytes,0);Ok(())
   })).unwrap();
  }
  caller.refreshed_turn(q,|cx|cx.with_original_work_loan(0,cx.original_absolute_deadline_us(),|cx|{let before=cx.retained_progress();let work=cx.original_work_units_spent();if bytes{PREPAID_BYTES.close_returned_step(cx)?;}else{PREPAID_PAGES.close_returned_step(cx)?;}assert_eq!(cx.retained_progress(),before);assert_eq!(cx.original_work_units_spent(),work);Ok(())})).unwrap();
  for _ in 0..law["maximumCloseTurns"].as_u64().unwrap(){let retained=if bytes{PREPAID_BYTES.retains_source(source)}else{PREPAID_PAGES.retains_source(source)};if !retained{break}caller.refreshed_turn(q,|cx|if bytes{PREPAID_BYTES.close_returned_step(cx)}else{PREPAID_PAGES.close_returned_step(cx)}).unwrap();}
  assert!(!if bytes{PREPAID_BYTES.retains_source(source)}else{PREPAID_PAGES.retains_source(source)});caller.retire(bank);
 }
}
